import{_ as i,c as e,h as p,a as t}from"./app-BIfOkl3-.js";const o={};function r(s,a){return t(),e("div",null,a[0]||(a[0]=[p('<link rel="stylesheet" href="/css/font-style.css"><h2 id="前言" tabindex="-1"><a class="header-anchor" href="#前言"><span>前言</span></a></h2><p> <s>没错，这是一篇书评。如各位所见我已经很久没有写过这样的随笔/书评了，因为绝大多数时间拿来陪“我家那位小朋友”（因为在我看来她确实十分可爱，有时脑子里会感觉她像个小孩子，可爱可爱），我也十分愿意陪她在一起玩。近来读他人博客吐槽我写的文章颇失语言简练性，一些文学性质的内容不易被察觉...所以本篇文章尽可能的使用人话来写，当然一些不明不白的内容也会尽可能的加批注。</s></p><p> 这是二编修改，至于为什么会有二遍修改我不会多做赘述。关于文章形式与语言风格我会依旧按照原先的方法进行书写，必要的话我会加注释。</p><p> 这本书是我在去年买的，看了很久，但却不尽人意：一是我很少具备艺术天赋，对于抽象的描述向来不擅长理解；二是这本书的语言风格对于我而言有些古怪，像似失去严谨性的抽象论文。但不可置疑的是，这是一本十分有趣的书。作者在本书的内容上狠下功夫，思想观念上又十分被大众所理解和接纳，所以我认为这是一本可以常翻常读，即便读起来很别扭。</p><p> 进一步来说，本书的内容和观念十分适合想要了解艺术的“新人”（事实上这是一本十分权威的书，同时也是一本接近“大白话”的书）。贡布里希围绕“如何在现有的画布/材料上更好的表现事物”为主，一步步推进艺术发展的脚步。从早期的埃及平面律、希腊开始有古板的画法和雕刻、世纪初的各种新的探索以及后期文艺复兴的透视法和朦胧法...这些都是主要线索的体现。</p><p> 需要澄清艺术不是神秘学家的玩具，它是具体的。按照原书的说法，是先有的艺术家，再有的艺术这个概念。贡布里希本人反感那些过分强调采用“内心、儿童视角”进行创作的行为，因为从艺术源头出发，它既服务于人，又来源于生活。过分强调艺术的神秘性将失去严谨，并且容易引起过分夸大和不必要的过分解读。</p><p> 回到本篇文章，没有人愿意看一篇艺术综论（我的文章很少会有吸引人的地方（因为趣味性较少。所以我会挑重点说、挑我感兴趣的说，不按照发展而是梦到哪里说哪里。</p><h2 id="艺术家与艺术" tabindex="-1"><a class="header-anchor" href="#艺术家与艺术"><span>艺术家与艺术</span></a></h2><blockquote><p><strong>&quot;实际上没有艺术这种东西，只有艺术家而已。&quot;</strong> ——贡布里希</p></blockquote><p> 相信作者在开头写这么一句话是有原因的，因为在现在看来，很多艺术家空空拥有一副自圆其说的道理，缺乏基本的观念致使讨论成为一人的主场、艺术成分被过度夸大。所以并不存在什么艺术，我们比起讨论艺术本身，不如将视角放在艺术家的创作动机和作品功能性上。当然我们也应但看到全部内容，失真的探讨不值一提。</p><p> 当我们知道这样的事情，再来看前几章的内容，我们就会发现古早的艺术作品来源于人们的各种需求，工匠、画家和雕刻家都可以被叫做艺术家，他们的作品也全部来自于委托需求而非本意。原始社会的祭祀图腾更是，这些作品都附有神秘色彩用于辟邪、驱魔等作用。直到希腊时代，我们才出现不属于这一范畴的作品，有绝大多数作品都是艺术家本人用于探求而制作的。同样，在这一时期以前，艺术家也并未拥有如同中世纪欧洲那样的地位，仅作为谋生甚至更差存在。</p><p> 我本人更喜欢来自希腊时期、文艺复兴和印象主义（下文介绍）的艺术作品，倒不是这一时期多么优秀，而是朴素追求本质和卓越。拿希腊时期举例，即便艺术作品普遍以呆板毫无表情为主，但其雕刻展现的手法和细节可以看出，希腊艺术更偏向毫无保留的古典，这种风格十分戳我。</p><h2 id="斗争和探求" tabindex="-1"><a class="header-anchor" href="#斗争和探求"><span>斗争和探求</span></a></h2><p> 拜占庭艺术并没想讨好谁。金色背景像道屏障，把人间隔绝出去。人物虽僵直，面孔如出一辙，但还请不要归咎于画师技艺不精，他们本就无意摹仿肉眼所见的真实。教堂的马赛克为信仰而嵌，信徒只需辨认出圣容，比例透视并不要紧（此处可以搬出圣索菲亚大教堂，也是进来我9剧情里，奠基石所复现的建筑）。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/d/dd/Hagia_Sophia_Imperial_Gate_mosaic_2.jpg" alt="项目截图"></p><p> 而后来的罗马式建筑（或者叫<a href="https://zh.wikipedia.org/wiki/%E7%BD%97%E9%A9%AC%E5%BC%8F%E5%BB%BA%E7%AD%91" title="罗马式建筑" target="_blank" rel="noopener noreferrer">罗曼式建筑</a>，其兼有<a href="https://zh.wikipedia.org/wiki/%E8%A5%BF%E7%BD%97%E9%A9%AC" title="西罗马" target="_blank" rel="noopener noreferrer">西罗马</a>和<a href="https://zh.wikipedia.org/wiki/%E6%8B%9C%E5%8D%A0%E5%BA%AD%E5%BB%BA%E7%AD%91" title="拜占庭建筑" target="_blank" rel="noopener noreferrer">拜占庭建筑</a>的特色）承接了这份沉重。厚墙，窄窗，整座教堂如同一座石砌堡垒，雕刻亦随之粗砺，圣徒的身躯被强行塞进门楣的弧线里，姿态别扭得近乎荒诞，但这恰是那个时代的方法：料与空间逼迫匠人做出妥协。（比如我们的比萨斜塔教堂就是典例）</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/4/4f/Pisa_Cathedral_%26_Leaning_Tower_of_Pisa.jpg" alt="比萨斜塔教堂"></p><p> 后来的哥特式也是我较为喜欢的一种，即便它被批评家戏称为“哥特式”（注意最开始这个词是贬义词，指野蛮的日耳曼风格，由罗曼式建筑发展而来）。尖拱与飞扶壁将荷载从墙壁转移至骨架，墙体终可被凿穿，镶满彩绘玻璃。阳光第一次穿透教堂，呈现出近乎透明的质感。夏特尔大教堂（据说圣母在此显灵）的蓝窗至今为人津津乐道。据说配方早已失传，真假难辨，但这份神秘本身已足见其震慑力。（还有我们最熟悉的巴黎圣母院、米兰大教堂等也是哥特式建筑的代表）</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Chartres_-_Cathédrale_(2012.01)_08.jpg/1280px-Chartres_-_Cathédrale_(2012.01)_08.jpg" alt="夏特尔大教堂"></p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Notre-Dame_de_Paris%2C_4_October_2017.jpg/3840px-Notre-Dame_de_Paris%2C_4_October_2017.jpg" alt="巴黎圣母院"></p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Milan_Cathedral_from_Piazza_del_Duomo.jpg/1920px-Milan_Cathedral_from_Piazza_del_Duomo.jpg" alt="米兰大教堂"></p><p> 书中写中世纪的末尾聊到了乔托。他常被归入中世纪末尾，而非文艺复兴开端——其实这么排更妥当。他笔下的圣方济各故事已赋予人物实在的体量，衣褶不再是装饰性的线条，而是真切地包裹着躯体。瓦萨里记过一则轶事：乔托年少时随手在木板上画了个正圆，笔法之精准，让来人误以为他用了圆规。故事多半不真，却恰如其分地诠释了乔托的地位。他不依赖工具，倚仗的是眼与手的协调。这恰恰是中世纪迈出的第一步——宗教并未退场，只是开始允许身体与空间拥有实在的分量。</p><h2 id="复兴" tabindex="-1"><a class="header-anchor" href="#复兴"><span>复兴</span></a></h2><p> 据说布鲁内莱斯基站在佛罗伦萨广场上，用一块画板与一面镜子验证了透视法。说来轻巧，做来却重绘了绘画的规则。画面不再是象征的堆叠，而成了一扇可计算的窗户。马萨乔几乎立刻将此法用于壁画，《圣三位一体》中的纵深，竟让当时的观者怀疑墙壁真被凿穿了一个洞。佛罗伦萨的空气里开始弥漫一种新的数学的墨水和石粉的气味。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/d/d2/Masaccio_trinity.jpg" alt="圣三位一体"></p><p> 在瓦萨里杜撰出“Rinascita”（重生）一词时，大概没料到自己会将整整一个多世纪的艺术悉数塞进这两个字里。文艺复兴并非一场突如其来的觉醒，而是一群人对中世纪既有答案的不满，转而翻查古典的旧账。账本里尽是些希腊的雕塑，罗马的建筑...但他们要的是一套可以重新丈量世界的尺度。</p><p> 我们当然绕不开三杰，因为他们三个不是天才就是疯子。达·芬奇的笔记本简直是个人类好奇心的犯罪记录，包含解剖图、水流漩涡、飞行器草图、心脏瓣膜、地质层剖面，挤在同一页纸上。他画《蒙娜丽莎》据说拖了十几年，赞助人催得火急火燎，他自岿然不动（这种慢工出细活的脾性搁今天，怕是早被甲方骂得狗血淋头。却也正因这份不肯将就，才磨出了“晕涂法”——轮廓融进空气，不见一根死硬的线条。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg/960px-Mona_Lisa%2C_by_Leonardo_da_Vinci%2C_from_C2RMF_retouched.jpg" alt="蒙娜丽莎"></p><p> 画里的嘴角的微笑永远差那么一点就能读透，恰好卡在“谜”与“解”的缝隙间。后世有人拿X光扫过画布，发现底下至少叠了四层不同的构图，每一层都在微调那弧度。这大概就是达·芬奇的工作方式：画完不算完，画到对为止，而“对”的定义永远在往后挪。他三十出头时曾给米兰公爵写信求职，罗列了自己在工程、武器、水利上的本事，十项全能之后才顺带提了一句：“我也会画画。”这种不屑于只做画家的傲慢，恰好是文艺复兴另一面。艺术家不再甘心当手艺人（此时的艺术家地位到了巅峰），他们要的是智识上的全盘征服。</p><p> 再说米开朗基罗。他接西斯廷天顶画时，满心不情愿（被骗来又气愤的走掉，然后又被请了过来。他自认是雕刻家，不是画匠。可最终，他仰着脖子趴在脚手架上耗了四年。教皇儒略二世不止一次跑来催问工期，得到的答复永远是那句：“等画完的时候。”后世常将此解读为艺术家对权力的倔强抵抗。我倒觉得，这无非是两种不同的见解，甲方要效率，乙方追求极致。米开朗基罗的壁画里，身体全是被雕塑刀淬过的。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/d/db/Lightmatter_Sistine_Chapel_ceiling.jpg" alt="西斯汀小堂"></p><p> 先知和女巫的肌肉扭结在一起，连上帝的手指都带着凿痕般的力度。他在诗里写过：“我的胡子朝天，脖子像鸽子般窝在背上，画笔滴下的颜料在脸上织出彩色的路。”这画面滑稽且辛酸。他雕《大卫》时才二十多岁，一块被前人废弃的大理石，他硬是从里面刻出了一个少年。据说完工后，佛罗伦萨人开会讨论把它放哪儿，连达·芬奇也参与了——两人在广场上互相看不顺眼（笑死了，两个人是对欢喜冤家，果然天才不能见面），这大概算文艺复兴最著名的一场冷眼。米开朗基罗活到八十九岁，临终前还在敲凿另一块石头。他一生都在跟材料较劲，跟教皇较劲，跟自己的衰老较劲（据说米开朗基罗脾气暴躁。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Michelangelos_David.jpg/500px-Michelangelos_David.jpg" alt="大卫"></p><p> 拉斐尔则安静许多。他比前两位都年轻，也更刻苦，却走得最早，三十七岁便没了。他笔下的圣母温柔匀称，几乎不带那种挣扎的痕迹。《西斯廷圣母》里，圣母抱着圣婴从帷幕间走来，脚步轻得不像踩在地上。拉斐尔不追求解剖上的震撼，他要的是视觉上的和谐——每条线都在呼应另一条线，每块颜色都找到了它的邻居。他在梵蒂冈画的《雅典学院》更是把透视法和古典精神推到极致：柏拉图手指天，亚里士多德手指地，周围挤满了哲学家和数学家，每个人都在辩论。有意思的是，拉斐尔把自己也画了进去，藏在角落，戴着深色帽子，像一个谦逊的旁观者。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/e/ea/Raffael_051.jpg" alt="西斯廷圣母"></p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/c/c4/Escola_de_Atenas_-_Vaticano_2.jpg/960px-Escola_de_Atenas_-_Vaticano_2.jpg" alt="雅典学院"></p><p> 他死后被葬在万神殿，墓志铭上写：“他在世时，自然女神畏惧被他征服；他去世后，自然女神也畏惧随他而去。”这话虽夸张，却道出了拉斐尔在那个年代的分量——他把文艺复兴磨成了可以教的规矩，让后辈不用再从头摸索。他的画室里学徒成群，模板化的工作流程几乎像个作坊（有些富贵名家会委托拉斐尔，但因为工作量巨大，被安排给作坊的其他学徒，只有仅少一部分是拉斐尔独立完成），可偏偏每一幅圣母像都还带着那种柔和的体温。</p><h2 id="印象派与现代化斗争" tabindex="-1"><a class="header-anchor" href="#印象派与现代化斗争"><span>印象派与现代化斗争</span></a></h2><p> 印象派受影响于日本当时的绘画技术，经过贸易来到了欧洲地区。可以这么说，很大程度上印象派画家是一种前所未有的激烈绘画革命，他们摒弃了传统意义上的画的仔细详尽，而是退一步将绘画交给一瞬间的眼睛所见以及大脑思考。1865年的沙龙展上，当马奈把《奥林匹亚》挂上墙时，所有人无不震惊。准确来说这份震惊和愤怒来自这具身体直勾勾地盯着看画的人，它并没有神话垫背，也没有什么寓言遮羞。现场且只有骂声一片，据说展方后来把画挪到了看不清的高处，还派人守着。但马奈并没退，这场风波反倒把学院那套&quot;裸体必须披古典外衣&quot;的老规矩打破了。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/Manet%2C_Edouard_-_Olympia%2C_1863.jpg/960px-Manet%2C_Edouard_-_Olympia%2C_1863.jpg" alt="奥林匹亚"></p><p> &quot;印象派&quot;就是这么来的，它和“哥特式”一样，本来是拿来嘲讽的。1874年记者路易·勒鲁瓦看了莫奈的《日出·印象》，写文章挖苦这群人连张完整的画都画不齐，也就只配叫&quot;印象&quot;。被骂的画家倒也不着急，索性把这个骂名扣自己头上。他们撂下画室里那套精修细描的老规矩，扛着颜料箱就往户外跑，只管追着光打在物体上那一瞬间的样子。这样的画法看似是偷懒，但对眼力的要求反而更毒辣，色彩在颤动的光影里转瞬即逝，压根来不及打草稿。（热知识，当时莫奈和他的妻子在船上，这一景象被朋友马奈画了下来，取名：《船上画室中的莫奈》）</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/5/54/Claude_Monet%2C_Impression%2C_soleil_levant.jpg/960px-Claude_Monet%2C_Impression%2C_soleil_levant.jpg" alt="日出·印象"></p><p><img src="https://www.ss.net.tw/file/Manet117/file1.jpg" alt="船上画室中的莫奈"></p><p> 另一位塞尚跟他们一起展览过，却始终没真正融进去。如果说莫奈追光，那塞尚则追光底下那块地。他要的是绘画本身的骨架，致使同一座圣维克多山他画了几十遍，每一遍都在较劲颜色之间怎么摆才站得住，毕加索后来说塞尚是&quot;我们的父亲&quot;，这话看来并不轻。据说晚年他躲进普罗旺斯自己跟自己较劲，死后画室空着，几个苹果、一只瓶子、一块白布，道具还在，人却走了。所见这样的画面不得不承认他把&quot;结构&quot;这两个字焊进了现代绘画的骨头里。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/8/8b/Cézanne%2C_Paul_-_Still_Life_with_a_Curtain.jpg" alt="静物与窗帘"></p><p> 至于高更则走得更远，物理距离和精神距离都远（直接迈进原始社会。他辞了股票经纪人的差事，撂下妻儿，跑去布列塔尼，又跑去塔希提。他要找文明之外的那点&quot;野蛮&quot;，塔希提的妇女坐在沙滩上，皮肤是赭石色，裙子是橘红色，背景铺得平平的，色块和色块硬碰硬地挤在一起。他跟梵高在阿尔勒同住两个月，最后闹得不欢而散，梵高割耳朵那晚据说他转头就回了巴黎，再没见过面。晚年高更在南太平洋的小岛上穷困潦倒，画那些浓烈得快烧起来的画，卖不掉，他好像也不太在乎，留下一句&quot;我是野蛮人，也是小孩&quot;，语气平得像在陈述一件跟自己无关的事实...</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/b/b7/Gauguin.swineherd.750pix.jpg" alt="布列塔尼牧人"></p><p><img src="https://upload.wikimedia.org/wikipedia/commons/7/73/Paul_Gauguin_056.jpg" alt="沙滩上的塔西提女人"></p><p> 而梵高跟这两位都不一样，塞尚好似在拆结构，高更像望着内心深处的孩子，梵高却是把自己整个人扔进画布里的那种。麦田、向日葵、星空、柏树，他手下全带着一股揉皱又用力展开的劲道，笔触短而密，犹如神经末梢直接戳在画布上。他甚爱用黄色，但并不是阳光的那种黄，而是快要烧过头的黄。当时他写给弟弟提奥的信有六百多封，字里行间全在说颜色、说线条、说怎么把一个念头搬上画布（事实上，如果你看到过其中的信件，你便能感受出梵高的热情、想法，这是无法比拟的）。阿尔勒时期他画了三百多幅，卖出去的只有一幅，叫《红色葡萄园》。</p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg/3840px-Van_Gogh_-_Starry_Night_-_Google_Art_Project.jpg" alt="星空"></p><p><img src="https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Vincent_Willem_van_Gogh_128.jpg/1280px-Vincent_Willem_van_Gogh_128.jpg" alt="向日葵"></p><p> 若一个人活着的每一天都在画，画的每一幅都卖不掉，还是每天在画，这里头有种朴素得不太好听、却很结实的东西，我每次想起还是会愣一下。就像现在我们常说的热爱...</p><h2 id="未尽的故事" tabindex="-1"><a class="header-anchor" href="#未尽的故事"><span>未尽的故事</span></a></h2><p>到这里，贡布里希的书其实还剩后半本，但那部分属实对我不太感冒。我只想说回开头那句话</p><blockquote><p><strong>&quot;实际上没有艺术这种东西，只有艺术家而已。&quot;</strong></p></blockquote><p> 读完整本，我才慢慢咂摸出这句话的另一层意思。贡布里希意不在贬低艺术，他是在把艺术从神坛上拽下来，放回人的手里。那些壁画、雕塑、教堂、画布，从来并非某个叫&quot;艺术&quot;的幽灵凭空变出来的，而是一个个具体的人，在具体的某个下午，对着具体的难题，一笔一笔抠出来的。</p><p> 乔托画圆的时候，马萨乔凿穿墙壁的时候，米开朗基罗仰着脖子滴颜料的时候，莫奈追着光跑的时候，梵高把神经末梢戳进画布的时候。他们都不知道自己在&quot;创造艺术&quot;。他们只是在解决眼前那个问题，究竟怎么让这个人站得住？怎么让这束光留得下来？怎么让自己今晚睡得着？</p><p> 贡布里希写这本书，大概也是这个意思。你不需要天赋，不需要&quot;艺术细胞&quot;，你只需要愿意停下来，看一幅画，问一句：这人当时想干嘛？何意味？</p><p> 这个问题问多了，那些僵直的圣徒、扭结的肌肉、颤动的光影、燃烧的黄，就都会从墙上走下来，变成人和人之间最普通的那种对话。关于怎么活，关于怎么看见，关于怎么在有限的时间里，把自己那点执拗，凿进什么东西里。</p><p> 而未尽之事，且待更有意者书写</p>',61)]))}const n=i(o,[["render",r]]),_=JSON.parse('{"path":"/posts/BookReview/storyOfart.html","title":"艺术的故事","lang":"en-US","frontmatter":{"title":"艺术的故事","description":"艺术的故事","date":"2026-07-23T00:00:00.000Z","timeline":true,"head":[["meta",{"name":"keywords","content":"艺术、艺术史"}],["meta",{"name":"description","content":"艺术的故事"}],["meta",{"name":"author","content":"RobinElysia"}]],"category":["RobinElysia"],"tag":["书评"]},"headers":[{"level":2,"title":"前言","slug":"前言","link":"#前言","children":[]},{"level":2,"title":"艺术家与艺术","slug":"艺术家与艺术","link":"#艺术家与艺术","children":[]},{"level":2,"title":"斗争和探求","slug":"斗争和探求","link":"#斗争和探求","children":[]},{"level":2,"title":"复兴","slug":"复兴","link":"#复兴","children":[]},{"level":2,"title":"印象派与现代化斗争","slug":"印象派与现代化斗争","link":"#印象派与现代化斗争","children":[]},{"level":2,"title":"未尽的故事","slug":"未尽的故事","link":"#未尽的故事","children":[]}],"git":{},"filePathRelative":"posts/BookReview/storyOfart.md","excerpt":"<link rel=\\"stylesheet\\" href=\\"/css/font-style.css\\">\\n<h2>前言</h2>\\n<p> <s>没错，这是一篇书评。如各位所见我已经很久没有写过这样的随笔/书评了，因为绝大多数时间拿来陪“我家那位小朋友”（因为在我看来她确实十分可爱，有时脑子里会感觉她像个小孩子，可爱可爱），我也十分愿意陪她在一起玩。近来读他人博客吐槽我写的文章颇失语言简练性，一些文学性质的内容不易被察觉...所以本篇文章尽可能的使用人话来写，当然一些不明不白的内容也会尽可能的加批注。</s></p>\\n<p> 这是二编修改，至于为什么会有二遍修改我不会多做赘述。关于文章形式与语言风格我会依旧按照原先的方法进行书写，必要的话我会加注释。</p>"}');export{n as comp,_ as data};
